import java.util.Scanner;
import java.math.BigInteger;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int m = scanner.nextInt();

        if (n == 1) {
            System.out.println(0);
            return;
        }

        long[] current = {1};
        long resultSum = 0;

        for (int i = 2; i <= n; i++) {
            int length = ((i - 1) * i) / 2 + 1;
            long[] nextList = new long[length];

            long[] prefixSum = new long[current.length + 1];
            for (int idx = current.length - 1; idx >= 0; idx--) {
                prefixSum[idx] = (prefixSum[idx + 1] + current[idx]) % m;
            }

            for (int w = 0; w < length; w++) {
                int leftIdx = Math.max(0, w + 1 - i);
                int rightIdx = Math.min(current.length - 1, w);
                long val = prefixSum[leftIdx] - (rightIdx + 1 < prefixSum.length ? prefixSum[rightIdx + 1] : 0);
                nextList[w] = ((val % m) + m) % m;
            }

            long[] eArr = new long[prefixSum.length];
            long[] fArr = new long[prefixSum.length];

            for (int w = 0; w < prefixSum.length - 1; w++) {
                eArr[w + 1] = (eArr[w] + prefixSum[w]) % m;
                fArr[w + 1] = (fArr[w] - w * prefixSum[w]) % m;
                fArr[w + 1] = ((fArr[w + 1]) % m + m) % m;
            }

            int R = current.length;
            long temp_b = 0;

            int startIdx1 = Math.max(0, current.length - i);
            for (int jj = startIdx1; jj < current.length - 1; jj++) {
                int L = jj + 2;
                int R_idx = i + jj;
                long val1 = (eArr[R] - eArr[L] + m) % m;
                long val2 = (fArr[R] - fArr[L] + m) % m;
                long term = (((val1 * (i + 1 + jj)) % m) + val2) % m;
                temp_b = (temp_b + (term * current[jj]) % m) % m;
            }

            for (int jj = 0; jj < current.length - i; jj++) {
                int L = jj + 2;
                int R_idx = i + jj;
                long val1 = (eArr[R_idx + 1] - eArr[L] + m) % m;
                long val2 = (fArr[R_idx + 1] - fArr[L] + m) % m;
                long term = (((val1 * (i + 1 + jj)) % m) + val2) % m;
                temp_b = (temp_b + (term * current[jj]) % m) % m;
            }

            long perm = permutation(n, n - i, m);
            resultSum = (resultSum + (temp_b * perm) % m) % m;

            current = nextList;
        }

        System.out.println(resultSum % m);
        scanner.close();
    }

    private static long permutation(int n, int k, int m) {
        long res = 1;
        for (int i = 0; i < k; i++) {
            res = (res * (n - i)) % m;
        }
        return res;
    }
}

